    const inR=p=>lay.rooms.find(r=>p[0]>r.x0 && p[0]<r.x1 && p[2]>r.z0 && p[2]<r.z1), RI=tr.P.map((p,i)=>{ const s=i*tr.ds; if(s<mkS.in || s>mkS.out) return -1; const r=inR(p); return r?r.i:0; }); H.RI=RI;
